	var pos int32 = from
	var t int32 = 0
	var avail int32 = 0
	var rb int32 = 0
	var i int32 = 0
	var x int32 = 0
	var a int32 = 0
	var b int32 = 0
	var c int32 = 0
	var hasPrev int32 = 0
	var v int32 = 0
	for pos < to {
		t = port.CellsAt(in, pos)
		pos += 1
		if t > 4 {
			return 4
		}
		rb = port.CellsLen(out)
		hasPrev = 0
		if (rb - base0) >= rowb {
			hasPrev = 1
		}
		avail = to - pos
		if avail > rowb {
			avail = rowb
		}
		i = 0
		for i < avail {
			x = port.CellsAt(in, pos+i)
			a = 0
			b = 0
			c = 0
			if i >= bpp {
				a = port.CellsAt(out, (rb+i)-bpp)
			}
			if hasPrev == 1 {
				b = port.CellsAt(out, (rb+i)-rowb)
				if i >= bpp {
					c = port.CellsAt(out, ((rb+i)-rowb)-bpp)
				}
			}
			v = x
			if t == 1 {
				v = x + a
			}
			if t == 2 {
				v = x + b
			}
			if t == 3 {
				v = x + ((a + b) / 2)
			}
			if t == 4 {
				v = x + pfPaeth(a, b, c)
			}
			port.CellsPush(out, v&255)
			i += 1
		}
		pos += avail
	}
	return 0
