func PfPredict(in *port.Cells, from int32, to int32, out *port.Cells, pred int32, colors int32, bpc int32, columns int32) int32 {
	// Apply /Predictor to in[from, to), appending to out: 1 is no
	// prediction, 2 TIFF (8 or 16 bits), 10-15 PNG. The parameters are
	// validated: colors 1-32, bpc 1/2/4/8/16, columns 1 to 2^24, and a
	// row no larger than 2^28 bits; anything else is `bad-predictor`.
	if pred == 1 {
		var k int32 = from
		for k < to {
			port.CellsPush(out, port.CellsAt(in, k))
			k += 1
		}
		return 0
	}
	if (colors < 1) || (colors > 32) || (columns < 1) || (columns > 16777216) {
		return 4
	}
	if (bpc != 1) && (bpc != 2) && (bpc != 4) && (bpc != 8) && (bpc != 16) {
		return 4
	}
	var rowb int32 = (((colors * bpc) * columns) + 7) / 8
	var bpp int32 = ((colors * bpc) + 7) / 8
	if pred >= 10 {
		return pfPng(in, from, to, out, rowb, bpp)
	}
	if (pred == 2) && ((bpc == 8) || (bpc == 16)) {
		return pfTiff(in, from, to, out, rowb, colors, bpc)
	}
	return 4
}

func PfRun(code int32, src []byte, s int32, e int32, out *port.Cells, st *port.Cells, early int32) int32 {
	// Run the filter `code` (a `pf-filter`) over src[s, e), appending to
	// out; `st` is scratch for LZW and Flate. Crypt is the identity (an
	// encrypted document is decrypted before its filters run). The image
	// codecs (DCT, JPX, CCITT, JBIG2) are not here: `image-filter`, and
	// `out` is untouched, for the caller to hand to the host's
	// `ImageDecode` (D005). Anything else is `unsupported-filter`.
	if code == 1 {
		return PfHex(src, s, e, out)
	}
	if code == 2 {
		return PfA85(src, s, e, out)
	}
	if code == 3 {
		return PfLzw(src, s, e, out, st, early)
	}
	if code == 4 {
		return PfFlate(src, s, e, out, st)
	}
	if code == 5 {
		return PfRl(src, s, e, out)
	}
	if code == 6 {
		var k int32 = s
		for k < e {
			port.CellsPush(out, pdfsrc.PsU8(src, k))
			k += 1
		}
		return 0
	}
	if (code >= 7) && (code <= 10) {
		return 10
	}
	return 9
}
